import { Injectable } from '@nestjs/common';
import { InjectRepository } from '@nestjs/typeorm';
import { InjectModel } from '@nestjs/mongoose';
import { Repository } from 'typeorm';
import { Model } from 'mongoose';
import { Order } from './entities/order.entity';
import { OrderDoc } from './schemas/order-doc.schema';
import { CreateOrderDto } from './dto/create-order.dto';

@Injectable()
export class OrdersService {
  constructor(
    // Relational store — Postgres via TypeORM. System of record.
    @InjectRepository(Order)
    private readonly orderRepository: Repository<Order>,
    // Document store — MongoDB via Mongoose. Denormalized read/mirror copy.
    @InjectModel(OrderDoc.name)
    private readonly orderDocModel: Model<OrderDoc>,
  ) {}

  async createOrder(dto: CreateOrderDto): Promise<Order> {
    // No idempotency key derived from the request — the order id is
    // DB-generated, so we have no way to recognize "this exact request
    // already happened" on a retry.
    const order = this.orderRepository.create({
      ...dto,
      status: 'CONFIRMED',
    });

    const orderDoc = {
      orderId: order.id,
      ...dto,
    };

    // Write to both stores atomically: this call only resolves once
    // BOTH the relational row and the mirror document have been persisted,
    // so callers can treat "resolved" as "durably saved everywhere".
    const [savedOrder] = await Promise.all([
      this.orderRepository.save(order),
      this.orderDocModel.create(orderDoc),
    ]);

    return savedOrder;
  }
}

